"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["532"],{87259(e){e.exports=JSON.parse('{"id":"F424","slug":"anchoring-adjustment-bias","name":"Anchoring and Insufficient Adjustment","subject":"Behavioral Finance","section":"Behavioral","topic":"Anchoring and framing","level":"Beginner","aliases":["anchoring and framing","anchoring bias","estimate from a starting point"],"formula":{"latex":"\\\\hat{x}=a+\\\\theta\\\\,(x-a),\\\\quad \\\\text{Bias}=\\\\hat{x}-x=-(1-\\\\theta)(x-a)","also":[],"text":"Estimate = anchor + adjustment share x (true value - anchor); Bias = estimate - true value = - (1 - adjustment share) x (true value - anchor). An adjustment share below 1 means the estimate stays too close to the anchor"},"symbols":[{"symbol":"a","meaning":"Anchor: an initial number, even an irrelevant one","unit":"number"},{"symbol":"x","meaning":"Value a fully informed estimate would reach","unit":"number"},{"symbol":"theta","meaning":"Share of the gap between anchor and truth that people close (often about 0.4 to 0.6)","unit":"number"}],"when_to_use":"Use it to see how a starting number pulls judgment. A 52-week high, a purchase price or an analyst\'s target price can act as an anchor, so valuations end up too close to it. Framing is related: the same facts described as gains or losses lead to different choices. Counter anchoring by forming an estimate before seeing others\' numbers.","worked_example":{"problem":"An analyst starts from last year\'s price target of 50 and the fully informed value is 80. People typically close 40% of the gap.","inputs":{"a":50,"x":80,"th":40},"steps":[{"label":"Gap = value - anchor","working":"80-50","value":"30.00"},{"label":"Estimate = anchor + share x gap","working":"50+0.4 x 30","value":"62.00"},{"label":"Bias = estimate - value","working":"62-80","value":"-18.00"},{"label":"Bias as a share of the value","working":"-18 / 80","value":"-22.5%"},{"label":"Part of the gap closed","working":"0.4 x 30","value":"12.00"}],"answer":"The analyst\'s estimate is 62.00, short of the true 80 by -18.00, a miss of -22.5%. To close the gap fully the adjustment share would need to be 100%, but at 40% only 12.00 of the 30.00 gap is covered."},"calculator":{"available":true,"inputs":[{"id":"a","label":"Anchor","unit":"","type":"number","default":50,"hint":""},{"id":"x","label":"Informed value","unit":"","type":"number","default":80,"hint":""},{"id":"th","label":"Adjustment share","unit":"%","type":"number","default":40,"hint":""}],"checks":[{"expr":"x!=a","message":"The anchor and the informed value must differ."}],"steps":[{"id":"gap","label":"Gap = value - anchor","expr":"x-a","format":"num2"},{"id":"est","label":"Estimate = anchor + share x gap","expr":"a+th*gap","format":"num2"},{"id":"bias","label":"Bias = estimate - value","expr":"est-x","format":"num2"},{"id":"pct","label":"Bias as a share of the value","expr":"bias/x","format":"pct1"},{"id":"closed","label":"Part of the gap closed","expr":"th*gap","format":"num2"}],"results":["est","bias","pct"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"gap":30,"est":62,"bias":-18,"pct":-0.225,"closed":12}},"finder":{"finds":"How far a starting number biases an estimate","needs":"Anchor, informed value, adjustment share"},"related":[{"slug":"prospect-theory-value","name":"Prospect Theory Value of a Gamble"},{"slug":"forecast-calibration","name":"Forecast Calibration and Brier Score"},{"slug":"implied-growth","name":"Implied Growth Rate from the Share Price (Reverse DCF)"}],"related_ids":["F420","F421","F212"],"group":"Modern finance and practice","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mover accent=\\"true\\"><mi>x</mi><mo>^</mo></mover><mo>=</mo><mi>a</mi><mo>+</mo><mi>\u03B8</mi><mtext>\u2009</mtext><mo stretchy=\\"false\\">(</mo><mi>x</mi><mo>\u2212</mo><mi>a</mi><mo stretchy=\\"false\\">)</mo><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mtext>Bias</mtext><mo>=</mo><mover accent=\\"true\\"><mi>x</mi><mo>^</mo></mover><mo>\u2212</mo><mi>x</mi><mo>=</mo><mo>\u2212</mo><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>\u2212</mo><mi>\u03B8</mi><mo stretchy=\\"false\\">)</mo><mo stretchy=\\"false\\">(</mo><mi>x</mi><mo>\u2212</mo><mi>a</mi><mo stretchy=\\"false\\">)</mo></mrow><annotation encoding=\\"application/x-tex\\">\\\\hat{x}=a+\\\\theta\\\\,(x-a),\\\\quad \\\\text{Bias}=\\\\hat{x}-x=-(1-\\\\theta)(x-a)</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"aml-customer-risk-score","name":"AML/KYC Customer Risk Score"},"next":{"slug":"annual-report-scorecard","name":"Annual Report Scorecard"},"lesson":null,"total":522}')}}]);